// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *ResLedgerEntry) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, ResLedgerEntryTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (entry_no)`,
		fmt.Sprintf("%s$Res_Ledger_Entry$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (resource_no, posting_date)`,
		fmt.Sprintf("%s$Res_Ledger_Entry$resource_date", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index resource_date: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (entry_type, chargeable, unit_of_measure_code, resource_no, posting_date)`,
		fmt.Sprintf("%s$Res_Ledger_Entry$type_resource", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index type_resource: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (entry_type, chargeable, unit_of_measure_code, resource_group_no, posting_date)`,
		fmt.Sprintf("%s$Res_Ledger_Entry$type_group", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index type_group: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (document_no, posting_date)`,
		fmt.Sprintf("%s$Res_Ledger_Entry$document", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index document: %w", err)
	}
	var keys []sift.Key
	for _, spec := range resLedgerEntrySIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, ResLedgerEntryTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, ResLedgerEntryTableName, keys)
}

// resLedgerEntrySIFTSpecs are the table's keys with sum_index_fields
func resLedgerEntrySIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{
		{
			Name:   "type_resource",
			Fields: []sift.Column{{Name: "entry_type", Kind: sift.KindInt}, {Name: "chargeable", Kind: sift.KindBool}, {Name: "unit_of_measure_code", Kind: sift.KindText}, {Name: "resource_no", Kind: sift.KindText}, {Name: "posting_date", Kind: sift.KindDate}},
			Sums:   []sift.Column{{Name: "quantity", Kind: sift.KindDecimal}, {Name: "total_cost", Kind: sift.KindDecimal}, {Name: "total_price", Kind: sift.KindDecimal}},
		},
		{
			Name:   "type_group",
			Fields: []sift.Column{{Name: "entry_type", Kind: sift.KindInt}, {Name: "chargeable", Kind: sift.KindBool}, {Name: "unit_of_measure_code", Kind: sift.KindText}, {Name: "resource_group_no", Kind: sift.KindText}, {Name: "posting_date", Kind: sift.KindDate}},
			Sums:   []sift.Column{{Name: "quantity", Kind: sift.KindDecimal}, {Name: "total_cost", Kind: sift.KindDecimal}, {Name: "total_price", Kind: sift.KindDecimal}},
		},
	}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *ResLedgerEntry) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := fmt.Sprintf("%s$%s", t.company, ResLedgerEntryTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range resLedgerEntrySIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, ResLedgerEntryTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: ResLedgerEntryTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, ResLedgerEntryTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

