	// buffers its rows — a one-row buffer would end the Next at once)
	if t.currentRows != nil {
		t.currentRows.Close()
		t.currentRows = nil
	}
	t.bufferedRecords = nil
	t.limit, t.offset, t.descending = savedLimit, savedOffset, savedDescending
	t.seek, t.seekArgs = "", nil
